@startuml

class Location {
  + Address : string
}

class Driver {
  + FirstName : string
  + LastName : string
}

abstract class Vehicle {
  + VehicleNumber : string
}

class Truck {
  + Weight : float
}

class Car {
  + Seats : int
}

class Van {}

class Order {
  + Origin : string
  + Destination : string
  + ExecutionDate : date
}

Location "1" *-- "1..*" Driver
Location "1" *-- "1..*" Vehicle
Vehicle --|> Truck
Vehicle --|> Car
Vehicle --|> Van

Driver "1" -- "0..1" Order
Driver "0..1" -- "0..*" Vehicle

@enduml

